args.command:
run() { printf '%-25s => ' "$2"; /workspace/dataset/test4_executable "$1" | tr '\n' ' '; echo; }
mk() { local n=$1; local s=""; for ((i=0;i<n;i++)); do s+="a"; done; printf '%s' "$s"; }
# single-label strings of various total lengths (label limit doesn't matter for domain check?)
for n in 255 256 257 300; do run "$(mk $n)" "single-$n"; done
